fn release(
    packages: &[String],
    receipt: Option<std::path::PathBuf>,
    global: &GlobalArgs,
) -> Result<ExitCode, CliError> {
    let selections = parse_selections(packages)?;
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let root = workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    if let Some(route) = ci_release_route(&workspace)?.filter(|_| !global.dry_run) {
        return Err(CliError::ReleaseRequiresCiRoute {
            reason: route.to_string(),
        });
    }
    let mode = if global.dry_run {
        LocalReleaseSource::Preview
    } else {
        LocalReleaseSource::Trusted
    };
    // The one `ls-remote` is network latency; it runs beside the plan rather than before it. Best effort: a tag that
    // never reached `origin` is a release that did not finish, whatever the plan says next.
    let probe = origin_tag_probe(&workspace).ok().flatten();
    let (missing, planned) = std::thread::scope(|scope| {
        let missing = probe.as_ref().map(|probe| scope.spawn(|| probe.missing(&runner)));
        let planned = plan_loaded_release(&workspace, &selections, mode);
        (missing.map(|handle| handle.join().unwrap_or_default()), planned)
    });
    for tag in missing.unwrap_or_default() {
        eprintln!("{}", tag_missing_from_origin_note(&tag));
    }
    let plan = planned?;
    if global.dry_run {
        write_release_preview(plan.as_ref(), global.format, &mut std::io::stdout())?;
        return Ok(ExitCode::SUCCESS);
    }
    let Some(plan) = plan else {
        print_nothing_to_release(global)?;
        return Ok(ExitCode::SUCCESS);
    };
    for diagnostic in &plan.diagnostics {
        eprintln!("warning: {}", diagnostic.message);
    }
    let intent = plan.intent;
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
    // A receipt records only full success; a partial run is recovered by rerunning.
    if let Some(path) = &receipt {
        callisto_model::atomic::probe_atomic_write(path, &permit).map_err(|source| CliError::Io {
            source,
            path: Some(path.clone()),
        })?;
    }
    let callisto_model::SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
        return Err(CliError::ReleaseEnvelopeInvalid {
            detail: "a local release source must be a Git commit".to_owned(),
        });
    };
    // A local run is its own orchestration, so both revisions are the source commit.
    let envelope =
        ReleaseRunEnvelopeV1::new(sha.clone(), &intent, None).map_err(|error| CliError::ReleaseEnvelopeInvalid {
            detail: error.to_string(),
        })?;
    let capability = validate_local_release_intent(&root, &locator, &runner, intent)?;
    let state = execute_release(&capability, &permit, &envelope, None)?;
    let receipt_document =
        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
            detail: error.to_string(),
        })?;
    if let Some(path) = &receipt {
        write_receipt(path, &receipt_document, &permit)?;
    }
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleaseReport {
                receipt: receipt_document.clone(),
            },
            global.dry_run,
        )?,
        OutputFormat::Text => {
            let released = capability.intent().decision.entries.len();
            match &receipt {
                Some(path) => emit_line(&format!(
                    "Released {released} package(s); receipt saved to {}",
                    path.display()
                ))?,
                None => emit_line(&format!("Released {released} package(s)"))?,
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

